class Solution {
public:
    vector<vector<string>> findLadders(string beginWord, string endWord, vector<string>& wordList) {
        unordered_set<string> words(wordList.begin(), wordList.end());
        if (!words.count(endWord)) return {};
        unordered_map<string, vector<string>> parents;
        unordered_set<string> layer = {beginWord};
        bool found = false;
        while (!layer.empty() && !found) {
            for (const auto& w : layer) words.erase(w);
            unordered_set<string> next_layer;
            for (const auto& word : layer) {
                string cand = word;
                for (int i = 0; i < (int)word.size(); i++) {
                    char original = cand[i];
                    for (char c = 'a'; c <= 'z'; c++) {
                        cand[i] = c;
                        if (words.count(cand)) {
                            if (cand == endWord) found = true;
                            next_layer.insert(cand);
                            parents[cand].push_back(word);
                        }
                    }
                    cand[i] = original;
                }
            }
            layer = next_layer;
        }
        if (!found) return {};
        vector<vector<string>> res;
        vector<string> path = {endWord};
        function<void(string)> dfs = [&](string curr) {
            if (curr == beginWord) {
                vector<string> p = path;
                reverse(p.begin(), p.end());
                res.push_back(p);
                return;
            }
            for (const auto& par : parents[curr]) {
                path.push_back(par);
                dfs(par);
                path.pop_back();
            }
        };
        dfs(endWord);
        return res;
    }
};

class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> words = new HashSet<>(wordList);
        if (!words.contains(endWord)) return new ArrayList<>();
        Map<String, List<String>> parents = new HashMap<>();
        Set<String> layer = new HashSet<>();
        layer.add(beginWord);
        boolean found = false;

        while (!layer.isEmpty() && !found) {
            words.removeAll(layer);
            Set<String> nextLayer = new HashSet<>();
            for (String word : layer) {
                char[] arr = word.toCharArray();
                for (int i = 0; i < arr.length; i++) {
                    char orig = arr[i];
                    for (char c = 'a'; c <= 'z'; c++) {
                        arr[i] = c;
                        String cand = new String(arr);
                        if (words.contains(cand)) {
                            if (cand.equals(endWord)) found = true;
                            nextLayer.add(cand);
                            parents.computeIfAbsent(cand, k -> new ArrayList<>()).add(word);
                        }
                    }
                    arr[i] = orig;
                }
            }
            layer = nextLayer;
        }
        if (!found) return new ArrayList<>();
        List<List<String>> res = new ArrayList<>();
        List<String> path = new ArrayList<>();
        path.add(endWord);
        dfs(endWord, beginWord, parents, path, res);
        return res;
    }

    private void dfs(String curr, String beginWord, Map<String, List<String>> parents, List<String> path, List<List<String>> res) {
        if (curr.equals(beginWord)) {
            List<String> copy = new ArrayList<>(path);
            Collections.reverse(copy);
            res.add(copy);
            return;
        }
        if (!parents.containsKey(curr)) return;
        for (String p : parents.get(curr)) {
            path.add(p);
            dfs(p, beginWord, parents, path, res);
            path.remove(path.size() - 1);
        }
    }
}

/**
 * @param {string} beginWord
 * @param {string} endWord
 * @param {string[]} wordList
 * @return {string[][]}
