var findLadders = function(beginWord, endWord, wordList) {
    const words = new Set(wordList);
    if (!words.has(endWord)) return [];
    const parents = new Map();
    let layer = new Set([beginWord]);
    let found = false;

    while (layer.size > 0 && !found) {
        for (const w of layer) words.delete(w);
        const nextLayer = new Set();
        for (const word of layer) {
            const arr = word.split('');
            for (let i = 0; i < arr.length; i++) {
                const orig = arr[i];
                for (let code = 97; code <= 122; code++) {
                    arr[i] = String.fromCharCode(code);
                    const cand = arr.join('');
                    if (words.has(cand)) {
                        if (cand === endWord) found = true;
                        nextLayer.add(cand);
                        if (!parents.has(cand)) parents.set(cand, []);
                        parents.get(cand).push(word);
                    }
                }
                arr[i] = orig;
            }
        }
        layer = nextLayer;
    }
    if (!found) return [];
    const res = [];
    const path = [endWord];
    function dfs(curr) {
        if (curr === beginWord) {
            res.push([...path].reverse());
            return;
        }
        const pars = parents.get(curr) || [];
        for (const p of pars) {
            path.push(p);
            dfs(p);
            path.pop();
        }
    }
    dfs(endWord);
    return res;
};
